style.css:
/* Bunny Blush — Roblox */
:root {
  /* swap these colors if you want */
  --my-pink: #f3dce3;
  --my-cream: #fffaf7;
  --my-rose: #c58e9e;
}

/* soft pink page */
body {
  background-color: var(--my-cream) !important;
  color: #8e6c78 !important;
}

/* gentle pastel look */
main, section, article {
  border-color: #f0dce3 !important;
}

/* softer links */
a {
  color: #bd8297 !important;
}

/* rounded images */
img {
  border-radius: 12px;
}
